type Jurisdiction={id:string;code:string;name:string;country:string;authorityName?:string;active:boolean|number};
type TaxCode={id:string;jurisdictionId?:string;code:string;name:string;rateMicros:number;calculation:"inclusive"|"exclusive";taxType:"sales"|"purchase"|"withholding";recoverablePercentMicros:number;salesAccountId?:string;purchaseAccountId?:string;active:boolean|number};
type TaxReturn={id:string;jurisdictionId:string;periodStart:string;periodEnd:string;status:string;outputTaxMinor:number;inputTaxMinor:number;withholdingMinor:number;netTaxMinor:number;lockedAt?:string;filedAt?:string;filingReference?:string};
