 const read=usePermission("accounts:read"),write=usePermission("accounts:write"),reportRead=usePermission("reports:read"),reportWrite=usePermission("reports:write"),[tab,setTab]=useState("codes"),[jurisdictions,setJurisdictions]=useState<Jurisdiction[]>([]),[codes,setCodes]=useState<TaxCode[]>([]),[returns,setReturns]=useState<TaxReturn[]>([]),[accounts,setAccounts]=useState<Account[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(""),[success,setSuccess]=useState(""),[modal,setModal]=useState<"jurisdiction"|"code"|"exemption"|"return"|null>(null),[editing,setEditing]=useState<TaxCode|null>(null);
