function TaxCodes({rows,jurisdictions,write,edit}:{rows:TaxCode[];jurisdictions:Jurisdiction[];write:boolean;edit:(x:TaxCode)=>void}){return rows.length===0?<EmptyState title="No tax codes" description="Create sales, purchase, or withholding tax treatment."/>:<div className="table-scroll"><table><thead><tr><th>Code</th><th>Jurisdiction</th><th>Type</th><th>Rate</th><th>Calculation</th><th>Recoverable</th><th>Accounts</th><th>Status</th><th/></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td><b>{x.code}</b><br/><small>{x.name}</small></td><td>{jurisdictions.find(j=>j.id===x.jurisdictionId)?.name||"—"}</td><td>{x.taxType}</td><td>{pct(x.rateMicros)}</td><td>{x.calculation}</td><td>{pct(x.recoverablePercentMicros)}</td><td><small>Sales: {x.salesAccountId||"—"}<br/>Purchase: {x.purchaseAccountId||"—"}</small></td><td><Badge tone={x.active?"success":"neutral"}>{x.active?"Active":"Inactive"}</Badge></td><td>{write&&<button onClick={()=>edit(x)}>Edit</button>}</td></tr>)}</tbody></table></div>}
function Jurisdictions({rows}:{rows:Jurisdiction[]}){return rows.length===0?<EmptyState title="No jurisdictions" description="Add the authority and country where tax is reported."/>:<div className="table-scroll"><table><thead><tr><th>Code</th><th>Name</th><th>Country</th><th>Authority</th><th>Status</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td><b>{x.code}</b></td><td>{x.name}</td><td>{x.country}</td><td>{x.authorityName||"—"}</td><td><Badge tone={x.active?"success":"neutral"}>{x.active?"Active":"Inactive"}</Badge></td></tr>)}</tbody></table></div>}
