function ExemptionModal({codes,close,done}:{codes:TaxCode[];close:()=>void;done:()=>void}){const[f,setF]=useState({contactId:"",taxCodeId:"",certificateNumber:"",reason:"",startsOn:"",endsOn:""}),[error,setError]=useState("");async function submit(e:FormEvent){e.preventDefault();if(f.startsOn&&f.endsOn&&f.startsOn>f.endsOn){setError("End date must be on or after the start date.");return}try{await post("/tax/exemptions",Object.fromEntries(Object.entries(f).filter(([,v])=>v)));done()}catch(x){setError((x as Error).message)}}return <Modal title="Record tax exemption" onClose={close}><form onSubmit={submit}>{error&&<Notice tone="danger">{error}</Notice>}<Field label="Tax code (optional)"><select value={f.taxCodeId} onChange={e=>setF({...f,taxCodeId:e.target.value})}><option value="">All applicable codes</option>{codes.map(x=><option key={x.id} value={x.id}>{x.code} · {x.name}</option>)}</select></Field><Field label="Contact ID (optional)" hint="Use the contact identifier when the exemption is customer- or supplier-specific."><input value={f.contactId} onChange={e=>setF({...f,contactId:e.target.value})}/></Field><Field label="Certificate number"><input value={f.certificateNumber} onChange={e=>setF({...f,certificateNumber:e.target.value})}/></Field><Field label="Reason"><textarea required value={f.reason} onChange={e=>setF({...f,reason:e.target.value})}/></Field><div className="form-grid"><Field label="Starts on"><input type="date" value={f.startsOn} onChange={e=>setF({...f,startsOn:e.target.value})}/></Field><Field label="Ends on"><input type="date" value={f.endsOn} onChange={e=>setF({...f,endsOn:e.target.value})}/></Field></div><div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button>Record exemption</Button></div></form></Modal>}
