function Runs({rows,employees,write,open,payslip}:{rows:Run[];employees:Employee[];write:boolean;open:(m:string,r?:Run)=>void;payslip:(r:Run,e:string)=>void}){const[employee,setEmployee]=useState("");return rows.length===0?<EmptyState title="No payroll runs" description="Calculate from an active rule or create a manual run."/>:<><div className="toolbar wrap"><select value={employee} onChange={e=>setEmployee(e.target.value)}><option value="">Select employee for payslip…</option>{employees.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.employeeNumber} · {x.name}</option>)}</select></div><div className="table-scroll"><table><thead><tr><th>Run</th><th>Period / pay date</th><th>Gross</th><th>Deductions</th><th>Employer cost</th><th>Net</th><th>Status</th><th/></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td><b>{x.number}</b><br/><small>{x.currency}</small></td><td>{x.periodStart} – {x.periodEnd}<br/><small>Pay {x.payDate}</small></td><td>{money(x.grossMinor,x.currency)}</td><td>{money(x.deductionsMinor,x.currency)}</td><td>{money(x.employerCostsMinor,x.currency)}</td><td><b>{money(x.netMinor,x.currency)}</b></td><td><Badge tone={tone(x.status)}>{x.status}</Badge></td><td><div className="row-actions">{write&&x.status==="draft"&&<button onClick={async()=>{if(confirm("Approve this calculated payroll?")){await post(`/payroll/runs/${x.id}/approve`,{});open("post",{...x,status:"approved"})}}}>Approve</button>}{write&&x.status==="approved"&&<button onClick={()=>open("post",x)}>Post</button>}{write&&x.status==="posted"&&<><button onClick={()=>open("batch",x)}>Payment batch</button><button onClick={()=>open("reverse",x)}>Reverse</button></>}{employee&&<button onClick={()=>payslip(x,employee)}>Payslip</button>}</div></td></tr>)}</tbody></table></div></>}
