function PostModal({run,accounts,close,done}:{run:Run;accounts:Account[];close:()=>void;done:()=>void}){const[f,setF]=useState({payrollExpenseAccountId:"",deductionsPayableAccountId:"",netPayableAccountId:"",employerExpenseAccountId:"",employerPayableAccountId:""}),[error,setError]=useState("");async function submit(e:FormEvent){e.preventDefault();if(!confirm(`Post ${run.number} to the general ledger?`))return;try{await post(`/payroll/runs/${run.id}/post`,Object.fromEntries(Object.entries(f).filter(([,v])=>v)));done()}catch(x){setError((x as Error).message)}}return <Modal title={`Post ${run.number}`} onClose={close}><form onSubmit={submit}>{error&&<Notice tone="danger">{error}</Notice>}<Notice tone="warning">Posting creates and posts the payroll journal. Account selection cannot be changed afterward; corrections require reversal.</Notice><Field label="Payroll expense"><Accounts rows={accounts} value={f.payrollExpenseAccountId} set={v=>setF({...f,payrollExpenseAccountId:v})}/></Field><Field label="Deductions payable"><Accounts rows={accounts} value={f.deductionsPayableAccountId} set={v=>setF({...f,deductionsPayableAccountId:v})}/></Field><Field label="Net pay payable"><Accounts rows={accounts} value={f.netPayableAccountId} set={v=>setF({...f,netPayableAccountId:v})}/></Field>{run.employerCostsMinor>0&&<><Field label="Employer cost expense"><Accounts rows={accounts} value={f.employerExpenseAccountId} set={v=>setF({...f,employerExpenseAccountId:v})}/></Field><Field label="Employer contribution payable"><Accounts rows={accounts} value={f.employerPayableAccountId} set={v=>setF({...f,employerPayableAccountId:v})}/></Field></>}<div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button>Post payroll</Button></div></form></Modal>}
function ReverseModal({run,close,done}:{run:Run;close:()=>void;done:()=>void}){const[f,setF]=useState({postingDate:today(),reason:"Payroll correction"}),[error,setError]=useState("");async function submit(e:FormEvent){e.preventDefault();if(!confirm(`Reverse posted payroll ${run.number}? This creates a reversing journal.`))return;try{await post(`/payroll/runs/${run.id}/reverse`,f);done()}catch(x){setError((x as Error).message)}}return <Modal title="Reverse payroll" onClose={close}><form onSubmit={submit}>{error&&<Notice tone="danger">{error}</Notice>}<Field label="Reversal date"><input required type="date" value={f.postingDate} onChange={e=>setF({...f,postingDate:e.target.value})}/></Field><Field label="Correction reason"><textarea required value={f.reason} onChange={e=>setF({...f,reason:e.target.value})}/></Field><div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button variant="danger">Confirm reversal</Button></div></form></Modal>}
