function StatutoryModal({runs,close,done}:{runs:Run[];close:()=>void;done:()=>void}){const[f,setF]=useState({payrollRunId:"",year:new Date().getFullYear(),period:String(new Date().getMonth()+1).padStart(2,"0"),authority:"",type:"PAYE",amount:0}),[error,setError]=useState("");async function submit(e:FormEvent){e.preventDefault();try{await post("/payroll/statutory-returns",{...f,payrollRunId:f.payrollRunId||undefined,amountMinor:Math.round(f.amount*100),payload:{}});done()}catch(x){setError((x as Error).message)}}return <Modal title="Create statutory return" onClose={close}><form onSubmit={submit}>{error&&<Notice tone="danger">{error}</Notice>}<Field label="Payroll run (optional)"><select value={f.payrollRunId} onChange={e=>setF({...f,payrollRunId:e.target.value})}><option value="">No linked run</option>{runs.map(x=><option key={x.id} value={x.id}>{x.number} · {x.payDate}</option>)}</select></Field><div className="form-grid"><Field label="Year"><input required type="number" min="2000" value={f.year} onChange={e=>setF({...f,year:Number(e.target.value)})}/></Field><Field label="Period"><input required value={f.period} onChange={e=>setF({...f,period:e.target.value})}/></Field><Field label="Authority"><input required value={f.authority} onChange={e=>setF({...f,authority:e.target.value})}/></Field><Field label="Return type"><input required value={f.type} onChange={e=>setF({...f,type:e.target.value})}/></Field><Field label="Amount"><input required type="number" min="0" step="0.01" value={f.amount} onChange={e=>setF({...f,amount:Number(e.target.value)})}/></Field></div><div className="modal-actions"><Button type="button" variant="secondary" onClick={close}>Cancel</Button><Button>Create draft</Button></div></form></Modal>}
function YearEnd({year,setYear,load,rows}:{year:string;setYear:(v:string)=>void;load:()=>void;rows:{employeeId:string;employeeNumber:string;name:string;grossMinor:number;deductionsMinor:number;netMinor:number}[]}){const[page,setPage]=useState(1),pageSize=25,pages=Math.max(1,Math.ceil(rows.length/pageSize)),safePage=Math.min(page,pages),start=(safePage-1)*pageSize,visible=rows.slice(start,start+pageSize),elementId=`payroll-year-end-${year}`,title=`Payroll year-end statements · ${year}`,totals=useMemo(()=>rows.reduce((a,x)=>({gross:a.gross+x.grossMinor,deductions:a.deductions+x.deductionsMinor,net:a.net+x.netMinor}),{gross:0,deductions:0,net:0}),[rows]);useEffect(()=>setPage(1),[year,rows.length]);const table=(items:typeof rows,all=false)=><table><thead><tr><th>Employee statement</th><th>Gross</th><th>Deductions</th><th>Net</th></tr></thead><tbody>{items.map(x=><tr key={x.employeeId}><td><b>{x.employeeNumber}</b><br/><small>{x.name}</small></td><td>{money(x.grossMinor)}</td><td>{money(x.deductionsMinor)}</td><td><b>{money(x.netMinor)}</b></td></tr>)}</tbody>{all&&<tfoot><tr><th>Year summary</th><th>{money(totals.gross)}</th><th>{money(totals.deductions)}</th><th>{money(totals.net)}</th></tr></tfoot>}</table>;return <><div className="toolbar wrap"><label>Tax year <input type="number" min="2000" value={year} onChange={e=>setYear(e.target.value)}/></label><Button variant="secondary" onClick={load}><RefreshCw size={14}/> Load year-end statements</Button></div>{rows.length===0?<EmptyState title="No year-end summary loaded" description="Choose a year to summarize posted and reversed payroll by employee."/>:<><div className="report-tools"><span className="report-tools__meta">{rows.length} employee{rows.length===1?"":"s"} · {pageSize} per page</span><div className="report-tools__actions"><Button variant="secondary" onClick={()=>downloadTableCsv(elementId,title)}><Download size={15}/> Export CSV</Button><Button variant="secondary" onClick={()=>printReportElement(elementId,title,"Statutory payroll year-end summary")}><Printer size={15}/> Print</Button></div></div><div className="table-scroll">{table(visible)}</div><div className="report-pagination"><span>Showing {start+1}–{Math.min(start+pageSize,rows.length)} of {rows.length}</span><Pagination page={safePage} pages={pages} onChange={setPage}/></div><div className="report-export-source" id={elementId}>{table(rows,true)}</div></>}</>}
function PayslipModal({data,runs,employees,write,close,error,success}:{data:Payslip;runs:Run[];employees:Employee[];write:boolean;close:()=>void;error:(s:string)=>void;success:(s:string)=>void}){const run=runs.find(x=>x.number===data.number),employee=employees.find(x=>x.employeeNumber===data.employeeNumber),[channel,setChannel]=useState<"email"|"portal">("email"),[recipient,setRecipient]=useState(employee?.email||"");async function pdf(){if(!run||!employee)return;try{const token=authStore.getAccess(),res=await fetch(`/api/v1/payroll/runs/${run.id}/payslips/${employee.id}/pdf`,{headers:{Authorization:`Bearer ${token}`}});if(!res.ok){const p=await res.json().catch(()=>({}));throw new Error(p.error?.message||"Unable to download payslip PDF")};const url=URL.createObjectURL(await res.blob()),a=document.createElement("a");a.href=url;a.download=`${data.employeeNumber}-${data.number}.pdf`;a.click();URL.revokeObjectURL(url)}catch(x){error((x as Error).message)}}async function deliver(){if(!run||!employee||!recipient.trim())return;try{await post(`/payroll/runs/${run.id}/payslips/${employee.id}/deliver`,{channel,recipient:recipient.trim()});success("Payslip delivery queued.")}catch(x){error((x as Error).message)}}return <Modal title={`Payslip · ${data.employeeNumber}`} onClose={close}><div className="metadata"><b>Employee</b><span>{data.name}</span><b>Payroll</b><span>{data.number}</span><b>Period</b><span>{data.periodStart} – {data.periodEnd}</span><b>Pay date</b><span>{data.payDate}</span></div><div className="staff-core-pay-summary"><span><small>Net salary</small><b>{money(data.netMinor,data.currency)}</b></span><span><small>Paid to date</small><b>{money(data.paidMinor||0,data.currency)}</b></span><span className={Number(data.balanceMinor)>0?"staff-balance-open":""}><small>Outstanding balance</small><b>{money(data.balanceMinor??data.netMinor,data.currency)}</b></span><span><small>Payment status</small><Badge tone={tone(data.paymentStatus||"unpaid")}>{String(data.paymentStatus||"unpaid").replaceAll("_"," ")}</Badge></span></div><Notice tone={Number(data.balanceMinor)>0?"warning":"success"}>{Number(data.balanceMinor)>0?"This payslip still has an outstanding salary balance. School staff salary installments can be recorded from School Management → Staff & teachers.":"This payslip is fully settled."}</Notice><div className="table-scroll"><table><thead><tr><th>Component</th><th>Type</th><th>Amount</th></tr></thead><tbody>{data.components.map((x,i)=><tr key={`${x.code}-${i}`}><td>{x.name}</td><td>{x.type}</td><td>{money(x.amountMinor,data.currency)}</td></tr>)}</tbody><tfoot><tr><th>Gross {money(data.grossMinor,data.currency)}</th><th>Deductions {money(data.deductionsMinor,data.currency)}</th><th>Net {money(data.netMinor,data.currency)}</th></tr></tfoot></table></div><Button variant="secondary" onClick={pdf}><Download size={15}/> Authenticated PDF</Button>{write&&<><h3>Deliver payslip</h3><div className="form-grid"><Field label="Channel"><select value={channel} onChange={e=>setChannel(e.target.value as "email"|"portal")}><option value="email">Email</option><option value="portal">Portal</option></select></Field><Field label="Recipient"><input value={recipient} onChange={e=>setRecipient(e.target.value)}/></Field></div><Button disabled={!recipient.trim()} onClick={deliver}><Send size={15}/> Queue delivery</Button></>}<div className="modal-actions"><Button variant="secondary" onClick={close}>Close</Button></div></Modal>}
